class AnthropicMessagesRequest(BaseModel):
    """
    Request body for `POST /v1/messages`, in Anthropic's shape.

    Measured Claude Code hints (`cache_control`, `context_management`)
    are accepted with a response header naming ignored settings;
    `thinking` chooses whether reasoning is returned. Metadata is
    discarded. Unknown top-level settings are explicitly rejected.
    This is a text, image, document and tool translation, not full parity.

    Consequently **this schema does not decide what is refused**.
    The refusals — documents it cannot carry, server-side tools,
    `mcp_servers`, more than four `stop_sequences` — are enforced
    against the raw request body by the implementation, with a 400
    naming the field, because a model that ignores extra keys cannot
    see the thing it is meant to reject. Read this schema as what
    the gateway *reads*, and the endpoint description as what it
    refuses.

    """

    model_config = ConfigDict(
        extra='allow',
    )
    model: str = Field(
        ...,
        description="A model id from `GET /v1/models`. Anthropic model names have\nno special meaning here: the id is resolved against this\ninstall's slots like any other, and a caller naming\n`claude-sonnet-4-5` gets whatever the operator mapped that\nto, or a 400.\n",
    )
    messages: list[AnthropicInputMessage] = Field(..., min_length=1)
    max_tokens: int = Field(
        ...,
        description="**Required by Anthropic's contract, and required here.**\nUnlike the OpenAI door, a missing value is a 400 rather than\na fill from the settings profile, because a client written\nagainst this wire always sends one and its absence means the\ncaller is not speaking this protocol.\n",
        ge=1,
    )
    system: str | list[AnthropicSystemBlock] | None = Field(
        None,
        description='A system prompt: a plain string, or a list of blocks.\n\nClaude Code sends three blocks, and the **first is not a\nprompt at all** — it is a billing header smuggled as prose\n(`x-anthropic-billing-header: …`). Any code that assumes\n`system[0]` is the instruction is wrong about the commonest\nclient. All blocks are concatenated in order into one\n`system` message.\n',
    )
    stream: bool | None = Field(
        False,
        description="When true the response is Anthropic's typed SSE stream.\n**Claude Code sets this on every request**, so the\nnon-streaming path of this endpoint is real but is not\nexercised by that client.\n",
    )
    temperature: float | None = Field(
        None,
        description="Anthropic's range is 0-1 where OpenAI's is 0-2. Passed\nthrough unscaled: the value means the same thing to a local\nengine either way, and rescaling would silently change what\na caller asked for.\n",
        ge=0.0,
        le=1.0,
    )
    top_p: float | None = Field(None, ge=0.0, le=1.0)
    top_k: int | None = Field(
        None,
        description='Carried to the backend since 2026-09-23. Before A2 it was\nsilently discarded despite controlling generation; from A2\nuntil 2026-09-23 it was refused with a 400, because the\ninternal request had nowhere to put it. Backends known to\nreject it are routed around.\n',
        ge=0,
    )
    stop_sequences: list[str] | None = Field(
        None,
        description='Up to four. A fifth is a 400 rather than a silent truncation\nto the first four, because dropping a stop sequence changes\nwhere the answer ends.\n',
    )
    tools: list[AnthropicToolDefinition] | None = Field(
        None,
        description='Tool definitions. Translated into the OpenAI function shape\nand carried to the backend unchanged.\n\nA backend that cannot carry tools is refused by name rather\nthan served without them — the same rule the OpenAI door\nstates, and for the same reason: a harness cannot tell "the\nmodel chose not to call one" from "nobody offered it any".\n',
    )
    tool_choice: AnthropicToolChoice | None = None
    metadata: dict[str, Any] | None = Field(
        None,
        description="Read and dropped. Claude Code puts a JSON *string* in\n`user_id` carrying a device id, an account uuid and a\nsession id; none of it is ours to keep, and the gateway's\nown request records already identify a request.\n",
    )
    thinking: dict[str, Any] | None = Field(
        None,
        description='**Read and dropped, never refused**, and the distinction was\nmeasured. Present on every Claude Code request, in three\nshapes: `{"budget_tokens": N, "type": "enabled"}` for a\nknown Claude id, `{"type": "adaptive"}` for an arbitrary\nlocal id, and **`null` when the caller set\n`MAX_THINKING_TOKENS=0`** — so even `"thinking" in body` is\ntrue for the one configuration asking for no thinking at\nall.\n\n**What it does decide, since 2026-09-23: whether the\nresponse carries `thinking` blocks, and whether their text\nis shown.** Non-null and not `{"type": "disabled"}` returns\nthe model\'s reasoning, when the backend reported any, as a\n`thinking` block ahead of the answer -- with the text, or\nwith the text empty and the reasoning carried in `signature`\nwhen `display` is `"omitted"`. Absent, null or disabled\nreturns none, which is Anthropic\'s own behaviour and keeps\n`content[0].text` pointing at the answer for every client\nthat never asked.\n\nWhat it does not decide: a `budget_tokens` is not enforced,\nand `disabled` hides the blocks without stopping the model\nthinking. Either is named on the ignored-settings response\nheader. The operator\'s `thinkingMode` governs what a local\nmodel actually does.\n',
    )
    output_config: dict[str, Any] | None = Field(
        None,
        description='**Accepted for `effort` only, and not enforced.** Claude Code\nsends `{"effort": "high"}` on every request -- measured\n2026-09-23 (2.1.207 with agent-sdk 0.3.280, beta header\n`effort-2025-11-24`), absent from the 2026-09-19 capture --\nand the unknown-field refusal A2 added turned that into a\n400 on the first request of every session: **Claude Code\ncould not use this door at all** until this field was named.\nHow hard a local model thinks is the operator\'s\n`thinkingMode`, exactly as for `thinking.budget_tokens`, so a\nnon-null value is named on the ignored-settings header.\n\nAny other key -- structured output\'s `format` above all --\nis refused with a 400 naming it: it changes what the answer\nis, and this door does not implement it.\n',
    )
    cache_control: dict[str, Any] | None = Field(
        None,
        description='Prompt-cache hints, read and dropped wherever they appear —\non system blocks, on the last user content block, and on\n`tool_result` blocks. A local engine owns its own KV cache\nand there is nothing here to honour.\n',
    )


class AnthropicCountTokensRequest(BaseModel):
    """
    Request body for `POST /v1/messages/count_tokens`: a Messages
    request without `max_tokens` (Claude Code sends `model`,
    `messages` and, per category, `system` or `tools`). Translated
    exactly as `POST /v1/messages` translates it, with the same
    refusals enforced against the raw body.

    """

    model_config = ConfigDict(
        extra='allow',
    )
    model: str
    messages: list[AnthropicInputMessage]
    system: str | list[AnthropicSystemBlock] | None = None
    tools: list[AnthropicToolDefinition] | None = None
    tool_choice: AnthropicToolChoice | None = None


class ModerationRequest(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    model: str | None = Field(
        None, description='Left out, the one moderation model this key may use (P6-1).'
    )
    input: str | ModerationTexts | ModerationParts = Field(
        ...,
        description="A string, an array of strings, or an array of parts. Every piece\nis a named schema: an inline array here was generated as `Input`\nand renamed the embeddings request's `Input` to `Input2`.\n",
    )


class ChatCompletionChunk(BaseModel):
    """
    One SSE frame of a streaming completion.
    """

    id: str
    object: Literal['chat.completion.chunk']
    created: int
    model: str
    choices: list[ChatCompletionChunkChoice]
    usage: CompletionUsage | None = None
    x_eugene_plexus: CompletionRoutingInfo | None = Field(
        None,
        description='Set on the **final frame only**, alongside `usage` — the\nsame place OpenAI puts its own end-of-stream extras.\nAbsent on every earlier frame, because the values are not\nknown until the completion is done. **One exception, asked\nfor:** with `stream_options.include_progress`, a progress\nchunk before the first token carries an `x_eugene_plexus`\nholding only `progress`, with `choices: []`.\n\nAdded at M8. Until then a streaming client could see no\nrouting information at all: the non-streaming response\ncarried this and the stream did not, so exactly the clients\nthat stream — the UI playground among them — were the ones\nthat could not tell which backend answered. Retained\nmetrics do not depend on this (they are recorded at the\nrouting hooks, which fire on both paths); this closes the\nmatching gap in what a caller can see.\n',
    )


class RoutingTableView(BaseModel):
    """
    The gateway's resolved routing table, as of the last refresh.
    The same snapshot requests are routed from, opened up so an
    operator can see why a request went where it did.

    """

    refreshed_at: AwareDatetime
    load_balancing: str | None = Field(
        None, description='The strategy in effect — the `loadBalancing` config value.'
    )
    slots: list[RoutingSlotView]
    unreachable_drivers: list[str] | None = Field(
        None, description='Drivers in the topology that did not answer `/v1/info`.'
    )
    outdated_drivers: list[OutdatedDriver] | None = Field(
        None,
        description='Drivers that answered `/v1/info` in the shape from before P1\n(a single `modelId`, no `models`). The gateway routes nothing\nto one: it would ignore the `model` a request names and\nanswer with its own. Listed so the console can say which\nmachine to update, rather than a model silently vanishing\nafter its gateway was updated and its worker was not.\n',
    )
    control_root: ControlRootView | None = None


class MessageContent1(
    RootModel[
        list[
            TextContentPart | ImageContentPart | InputAudioContentPart | FileContentPart
        ]
    ]
):
    root: list[
        TextContentPart | ImageContentPart | InputAudioContentPart | FileContentPart
    ] = Field(
        ...,
        description="Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: the gateway's `maxImagesPerRequest`\nper request (12 by default, at most 64, counted across the whole\nconversation), 5 MiB decoded each, 10 MiB decoded total, 16 million\npixels each, maximum dimension 8192. The inference-driver enforces\nthe ceiling of 64; the gateway enforces the setting.\n\nAudio (`input_audio`, WAV or MP3) and files (`file`, PDF) are\ninline too: at most 10 MiB decoded each, and every attachment in\nthe request together -- images, audio and files -- at most\n11 MiB decoded, which is what fits in the 16 MiB JSON body once\nbase64 has grown it by a third. Attachments ride on user messages\nonly. Remote URLs are never fetched, and a `file_id` is refused:\neach names a store this install does not have.\n",
        min_length=1,
    )


class ChatCompletionMessage(BaseModel):
    """
    OpenAI-shaped chat message. Intentionally *not* the shared
    `Message` schema: this one is on a wire contract we do not own,
    so it carries exactly OpenAI's fields and nothing of ours.
    Leaking a house field like `timestamp` into a payload an OpenAI
    SDK parses is how "compatible" quietly stops being true.

    """

    role: Role1 = Field(
        ...,
        description="`function` is the deprecated role for a function's result,\nanswering the assistant's `function_call` before it; it is\ncarried as a `tool` message answering that call (P2c).\n\n`developer` is OpenAI's newer name for the instruction role,\nsent by current SDKs and frameworks when they target a\nreasoning model. It reaches the backend as `system`, in\nplace -- local chat templates know only `system`, and the\ntwo mean the same thing to a model that is not OpenAI's.\nRefused with a 400 until 2026-09-23.\n",
    )
    content: str | MessageContent1 | None = Field(
        None,
        description="Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: the gateway's `maxImagesPerRequest`\nper request (12 by default, at most 64, counted across the whole\nconversation), 5 MiB decoded each, 10 MiB decoded total, 16 million\npixels each, maximum dimension 8192. The inference-driver enforces\nthe ceiling of 64; the gateway enforces the setting.\n\nAudio (`input_audio`, WAV or MP3) and files (`file`, PDF) are\ninline too: at most 10 MiB decoded each, and every attachment in\nthe request together -- images, audio and files -- at most\n11 MiB decoded, which is what fits in the 16 MiB JSON body once\nbase64 has grown it by a third. Attachments ride on user messages\nonly. Remote URLs are never fetched, and a `file_id` is refused:\neach names a store this install does not have.\n",
    )
    reasoning_content: str | None = Field(
        None,
        description="**On a response:** the model's reasoning for this turn, when\nthe backend reported it separately from `content`. The name\nis DeepSeek's and llama.cpp's, and the one OpenAI-compatible\nclients already parse (vLLM's `reasoning` is normalised to\nit). Absent when there was none or when the serving driver's\n`thinkingMode` is `off`.\n\n**On a request:** accepted on an `assistant` message and\nhanded back to the backend, so a tool loop resumes with the\nmodel's own earlier thinking -- a client that appends the\nresponse message verbatim sends it back, and llama.cpp\nrenders it into the prompt for templates that keep it.\n\nAdded 2026-09-23. Before it every token of a reasoning\nmodel's thinking was discarded one hop down, so a model that\nspent its whole budget thinking answered with an empty\n`content` and `finish_reason: length`, with nothing to say\nwhy.\n",
    )
    name: str | None = Field(None, description='Optional participant name, per OpenAI.')
    tool_calls: list[ToolCall] | None = Field(
        None,
        description='Set on an **assistant** message, naming the tools the model\nchose to call. The caller executes them and replies with one\n`tool` message per call, each carrying the matching\n`tool_call_id`.\n',
    )
    tool_call_id: str | None = Field(
        None,
        description='Required on a **tool** message: which call in the preceding\nassistant turn this is the result of. `content` is the\nresult, as a string — the caller serializes it.\n',
    )
    audio: ChatCompletionAudio | None = Field(
        None,
        description='On a response: the spoken answer (P2b). On a request:\nrefused with a 400, since it would name stored audio.\n',
    )
    function_call: FunctionCall | None = Field(
        None,
        description="The deprecated single function call (P2c). On a response, only\nwhen the request used `functions`. On a request's assistant\nmessage, it is carried as that turn's one tool call.\n",
    )
    annotations: list[ChatAnnotation] | None = Field(
        None,
        description="On a response: the web sources the answer cites (P2c). On a\nrequest's assistant message, accepted and not forwarded: it\ndescribes the text beside it and instructs nothing.\n",
    )


class ChatCompletionChoice(BaseModel):
    index: int
    message: ChatCompletionMessage
    logprobs: ChatLogprobs | None = Field(
        None, description="With `logprobs` true, the answer's; otherwise null."
    )
    finish_reason: FinishReason = Field(
        ...,
        description='`function_call` only when the request used the deprecated\n`functions`, in place of `tool_calls` (P2c).\n\n`stop` for a natural end or a matched stop sequence,\n`length` for hitting the token cap, `tool_calls` when the\nmodel stopped because it wants one or more tools run,\n`content_filter` when a safety classifier stopped it.\n\n**`content_filter` is OpenAI\'s own value and is carried\nsince 2026-09-19.** Before that the chain was\n`content_filter` → the driver\'s `error` → `stop`, so a\nfiltered answer arrived as a natural end and a caller had\nno way to tell a refusal from a reply. The same mistake as\n`tool_calls` → `stop` before 2026-09-11, one value along:\na state with no row of its own reported as its nearest\nneighbour.\n\nUntil 2026-09-11 this enum was `stop` and `length` only, and\nits description said so in as many words — "OpenAI\'s two\nvalues for a completion **without** tool calls". That\nsentence was the single occurrence of the string "tool"\nanywhere in this contract or the driver\'s, and it was an\naccurate description of a control plane no agent harness\ncould use.\n',
    )


class Message(BaseModel):
    """
    A single message in a conversation. Deliberately close to the
    OpenAI / Anthropic chat message format so drivers don't have to
    re-shape on every hop.

    """

    role: Role
    content: str | MessageContent1 | None = Field(
        None,
        description="Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: the gateway's `maxImagesPerRequest`\nper request (12 by default, at most 64, counted across the whole\nconversation), 5 MiB decoded each, 10 MiB decoded total, 16 million\npixels each, maximum dimension 8192. The inference-driver enforces\nthe ceiling of 64; the gateway enforces the setting.\n\nAudio (`input_audio`, WAV or MP3) and files (`file`, PDF) are\ninline too: at most 10 MiB decoded each, and every attachment in\nthe request together -- images, audio and files -- at most\n11 MiB decoded, which is what fits in the 16 MiB JSON body once\nbase64 has grown it by a third. Attachments ride on user messages\nonly. Remote URLs are never fetched, and a `file_id` is refused:\neach names a store this install does not have.\n",
    )
    toolCalls: list[dict[str, Any]] | None = Field(
        None,
        description="On an **assistant** message: the tool calls the model made,\nin OpenAI's `{id, type, function: {name, arguments}}` shape.\n\nDeliberately loose here. This is the *shared* schema, so a\ntightly-typed copy would be a third definition of the same\nobject alongside the gateway's and the driver's, and the one\nplace all three must agree is the wire format, which is\nOpenAI's and not ours to restate. The two API documents\ncarry the strict shapes.\n",
    )
    toolCallId: str | None = Field(
        None,
        description='On a **tool** message: which call this is the result of.\n`content` is the result, serialized by the caller.\n',
    )
    reasoning: str | None = Field(
        None,
        description="On an **assistant** message: the reasoning the model produced\nfor that turn, as the backend reported it separately from\n`content` (`reasoning_content` on llama.cpp, `reasoning` on\nvLLM). Handed back so the next turn of a tool loop reaches\nthe model with its own earlier thinking.\n\n**Load-bearing rather than decorative, and measured:**\nllama.cpp b10948 renders a history turn's reasoning into the\nprompt for templates that preserve it (Qwen3, gpt-oss) --\nthe same tool-loop request was 172 prompt tokens without it\nand 184 with a twelve-token canary. Dropped here, a model\nresuming a tool loop has forgotten why it called the tool.\n\nAbsent on every other role, and an adapter whose backend\nhas no such channel (the agentic CLIs, a hosted OpenAI\nendpoint) omits it upstream rather than inventing one.\n",
    )
    timestamp: AwareDatetime | None = Field(
        None, description='When the message was produced. Server-assigned if omitted.'
    )


class ChatCompletionRequest(BaseModel):
    """
    Supported chat settings only. Unknown properties, including nested message,
    tool and response-format properties, return 400 with a field name. Arbitrary
    JSON Schemas inside function parameters and response schemas are preserved.
    Validation errors do not echo request values. See docs/api-compatibility.md.

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    model: str = Field(
        ...,
        description='A model id from `GET /v1/models`. The gateway resolves it to\na backend; the client does not choose a backend.\n',
    )
    messages: list[ChatCompletionMessage] = Field(..., min_length=1)
    max_tokens: int | None = Field(
        None,
        description="Positive JSON integer generation limit; booleans, strings and floats\nare rejected. Null or absent uses the profile then gateway default.\nNormalized before defaults and preserved on every fallback attempt.\nEngine token accounting is not guaranteed to match OpenAI's.\n",
        ge=1,
    )
    max_completion_tokens: int | None = Field(
        None,
        description='Alias of max_tokens. If both are non-null they must be equal, otherwise\n400 names max_completion_tokens. Neither spelling takes precedence over\na conflicting value. This does not add reasoning-token support to engines.\n',
        ge=1,
    )
    temperature: float | None = Field(None, ge=0.0, le=2.0)
    top_p: float | None = Field(
        None,
        description='Nucleus sampling cutoff, carried to the backend.\n\n**This field was accepted, validated and discarded until\n2026-09-19**: `GenerateRequest` had no `topP` to put it in,\nso the value went no further than this schema and nothing\nwas logged. It has one now.\n',
        ge=0.0,
        le=1.0,
    )
    stop: str | Stop | None = Field(
        None,
        description='One stop sequence or up to four sequences; forwarded as an array.',
    )
    seed: int | None = Field(
        None,
        description='Passed through to backends that support deterministic\nsampling; dropped with a warning where they do not.\n\n**True since 2026-09-19 and unfulfillable before it** —\nthere was no `seed` on `GenerateRequest`, so the value was\ndropped by every backend and the warning this sentence\npromises was logged by none of them. A caller asking for a\nseed is asking for a reproducible answer and was getting a\ndifferent one each time, with nothing in the response to\nsay so.\n',
    )
    frequency_penalty: float | None = Field(
        None,
        description="Carried to the backend. Refused with 400 by backends that\ncannot honour it (the agentic CLIs; OpenAI models with a\nfixed sampler), which are skipped when choosing a backend\nrather than tried and failed.\n\n**Refused with a 400 at this door until 2026-09-23**, like\nthe four fields below it, although llama.cpp and vLLM both\ntake all of them: the internal request had nowhere to carry\nthem, and a refusal was the honest answer to that. Clients\nthat send them by default -- SillyTavern, Open WebUI's\nadvanced parameters -- could not use this door at all.\n",
        ge=-2.0,
        le=2.0,
    )
    presence_penalty: float | None = Field(
        None,
        description='Carried and refused exactly as `frequency_penalty` is.',
        ge=-2.0,
        le=2.0,
    )
    top_k: int | None = Field(
        None,
        description="**Not an OpenAI parameter.** A local-engine extension that\nllama.cpp and vLLM both read; 0 disables the cut. Refused\nby backends known to reject it -- OpenAI's own endpoint and\nthe agentic CLIs -- and those are routed around.\n",
        ge=0,
    )
    min_p: float | None = Field(
        None,
        description="**Not an OpenAI parameter.** llama.cpp's and vLLM's `min_p`,\ncarried and refused exactly as `top_k` is.\n",
        ge=0.0,
        le=1.0,
    )
    stream: bool | None = Field(
        False,
        description='When true the response is an SSE stream of\n`ChatCompletionChunk` objects terminated by `data: [DONE]`.\n',
    )
    user: str | None = Field(
        None,
        description='Ignored client annotation; not stored, forwarded or used as identity.',
    )
    metadata: dict[str, str] | None = Field(
        None,
        description='Ignored annotations; not provider storage or queryable metadata.',
    )
    safety_identifier: str | None = Field(
        None,
        description="A hint (P2c): carried to OpenAI's own API, which uses it for abuse\ndetection, and dropped for every other backend, none of which\nlists it. Not an authenticated identity here.\n",
        max_length=64,
    )
    prompt_cache_key: str | None = Field(
        None,
        description="A hint (P2c): OpenAI's cache routing key, carried to OpenAI's own\nAPI and dropped elsewhere. A hint changes where or how cheaply an\nanswer is made, never what it says, so dropping it is honest\nwhere refusing a setting is not. No OpenRouter model lists it\n(measured).\n",
        max_length=1024,
    )
    prompt_cache_retention: PromptCacheRetention | None = None
    service_tier: ServiceTier | None = None
    n: Literal[1] = Field(
        1,
        description='Only one completion is supported; any other non-null value returns 400.',
    )
    logprobs: bool | None = Field(
        None,
        description="Return each chosen token's log probability (P2c). Routes only to\na model that lists `logprobs` (149 on OpenRouter, measured),\nwhere it was refused with a 400 before 2026-09-28.\n",
    )
    top_logprobs: int | None = Field(
        None,
        description='How many alternatives per token, with `logprobs` true; refused without it.',
        ge=0,
        le=20,
    )
    logit_bias: dict[str, int] | None = Field(
        None,
        description="Token id (as a string) to a bias from -100 to 100, OpenAI's\nshape. A setting, routed as A2 says (141 models list it). Token\nids are the model's own, so the same bias means something else\non another model -- which is why it is never sent to one that\ndid not list it.\n",
    )
    reasoning_effort: ReasoningEffort | None = None
    verbosity: Verbosity | None = None
    prediction: Prediction | None = None
    web_search_options: WebSearchOptions | None = None
    functions: list[FunctionDefinition] | None = Field(
        None,
        description='**Deprecated by OpenAI; translated, not refused (P2c).** The same\nthing as `tools` with every tool a function, carried as tools.\nThe answer is given back in the deprecated shape too,\n`message.function_call` and `finish_reason: function_call`,\nbecause a client that sends this shape reads that one. The old\nAPI gave one call per turn; if a model asks for more, the first\nis given. **`parallel_tool_calls` is not sent for it**: set\nfalse, it would be an explicit setting, and A2 would route the\nrequest only to models that list it (12 of 455 on OpenRouter,\nmeasured). Refused together with `tools` or `tool_choice`.\n',
        max_length=128,
    )
    function_call: FunctionCallMode | FunctionCallName | None = Field(
        None,
        description='The deprecated `function_call`: `none`, `auto`, or `{"name"}` to\nforce one function. Translated to `tool_choice`.\n',
    )
    store: Literal[False] = Field(
        False,
        description='Only false is supported; provider completion storage is not implemented.',
    )
    stream_options: StreamOptions | None = Field(
        None,
        description="With streaming, true adds a usage-only chunk before DONE when the driver\nreports usage. False omits usage. If absent, retains Eugene's historical\nfinal choice chunk containing usage. Does not affect retained metrics.\n",
    )
    tools: list[Tool] | None = Field(
        None,
        description='Tools the model may call. Passed through to the backend\nunchanged; the gateway never invents, filters or reorders\nthem.\n\n**The gateway does not execute tools.** It carries the\ndefinitions down and the model\'s chosen calls back up, and\nthe caller runs them and sends the results as `tool` role\nmessages. That is OpenAI\'s contract and it is the one an\nagent harness implements.\n\nA backend that cannot carry tools is not silently stripped:\nthe request fails with a 400 naming the backend, because a\nharness that receives a plain answer where it expected a\ntool call has no way to tell "the model chose not to" from\n"nobody ever offered it the tools" — and the second is a\nbug that looks exactly like the first. `GET /v1/models`\nreports which models can.\n',
    )
    tool_choice: ToolChoice | NamedToolChoice | None = Field(
        None,
        description='How the model should use `tools`. `auto` is the default when\ntools are present, `none` forbids calling one, `required`\nforces at least one call, and an object names a specific\nfunction. Passed through; the gateway does not enforce it.\n',
    )
    parallel_tool_calls: bool | None = Field(
        None,
        description='Whether the model may request several tools in one turn.\nCarried when set and left absent when not, because the\nbackends disagree about the default -- llama.cpp assumes\nfalse, OpenAI true -- and filling one in would change what\none of them already does.\n',
    )
    response_format: ResponseFormat | None = None
    modalities: list[ChatModality] | None = Field(
        None,
        description='What the answer is made of. `["text"]` is the default;\n`["text", "audio"]` asks for a spoken answer and needs\n`audio`. Routes only to a model that confirms audio output.\nAdded 2026-09-28 (P2b).\n',
        min_length=1,
    )
    audio: ChatAudioRequest | None = None


class ChatCompletionResponse(BaseModel):
    id: str = Field(
        ..., description='Completion id, `chatcmpl-` prefixed as clients expect.'
    )
    object: Literal['chat.completion']
    created: int
    model: str = Field(
        ...,
        description='The model that actually served the request. Equal to the\nrequested id in the normal case; after a cascade it names\nwhat answered, which may differ.\n',
    )
    choices: list[ChatCompletionChoice]
    usage: CompletionUsage | None = Field(
        None, description='Present on the final chunk only.'
    )
    x_eugene_plexus: CompletionRoutingInfo | None = None


AnthropicContentBlock.model_rebuild()
